// since, with when each first moved to In progress or later, its labels and
// its children's points.
func (q *Queries) ListTimelineIssues(ctx context.Context, arg ListTimelineIssuesParams) ([]ListTimelineIssuesRow, error) {
	rows, err := q.db.Query(ctx, listTimelineIssues, arg.ProjectID, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTimelineIssuesRow{}
	for rows.Next() {
		var i ListTimelineIssuesRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.Title,
			&i.Status,
			&i.Priority,
			&i.TypeID,
			&i.ParentID,
			&i.StartOn,
			&i.DueOn,
			&i.Estimate,
			&i.AssigneeID,
			&i.AssigneeName,
			&i.StatusChangedAt,
			&i.StartedAt,
			&i.Labels,
			&i.Children,
			&i.ChildrenShipped,
			&i.ChildrenDone,
			&i.ChildrenPoints,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const moveUpcomingCycle = `-- name: MoveUpcomingCycle :execrows
UPDATE cycles SET starts_on = $1, ends_on = $2
WHERE id = $3 AND starts_on > $4::date AND closed_at IS NULL
`

type MoveUpcomingCycleParams struct {
	StartsOn pgtype.Date `json:"starts_on"`
	EndsOn   pgtype.Date `json:"ends_on"`
	ID       pgtype.UUID `json:"id"`
	Today    pgtype.Date `json:"today"`
}

// A new schedule redraws only the cycles that haven't started.
func (q *Queries) MoveUpcomingCycle(ctx context.Context, arg MoveUpcomingCycleParams) (int64, error) {
	result, err := q.db.Exec(ctx, moveUpcomingCycle,
		arg.StartsOn,
		arg.EndsOn,
		arg.ID,
		arg.Today,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

